source('highres_VisiumHD/analysis/hd_mp10_treg_endo_precommunication_v1/code/common.R');suppressPackageStartupMessages(library(spacexr));gate();
# Linux fork workers inherit the identical frozen namespace and one-thread BLAS.
# PSOCK on this host mixed doParallel worker namespaces (.doSnowGlobals failure).
trace('makeCluster',where=asNamespace('parallel'),tracer=quote(type <- 'FORK'),print=FALSE);
unit<-commandArgs(TRUE)[1]
if(file.exists(file.path(root,'tables',paste0(unit,'_rctd_summary.json'))) && Sys.getenv('HD_RECOMPUTE')!='1')quit(save='no')
ref<-readRDS(file.path(root,'models/fine_reference.rds'));labs<-factor(gsub('/','_',ref$metadata$label,fixed=TRUE));names(labs)<-colnames(ref$counts);reference<-Reference(ref$counts,labs,nUMI=colSums(ref$counts),n_max_cells=5000,min_UMI=100)
x<-as(readMM(file.path(root,'temporary',paste0(unit,'_ROI.mtx'))),'dgCMatrix');d<-rd(paste0(unit,'_ROI.tsv.gz'));g<-rd('hd_genes.tsv');G<-sparseMatrix(i=match(g$symbol,unique(g$symbol)),j=seq_len(nrow(g)),x=1);x<-G%*%x;rownames(x)<-unique(g$symbol);colnames(x)<-d$bin_id;xx<-x[intersect(rownames(x),rownames(reference@counts)),];keep<-d$qc_keep & colSums(xx)>=100
sp<-SpatialRNA(data.frame(x=d$x_um[keep],y=d$y_um[keep],row.names=d$bin_id[keep]),xx[,keep],colSums(xx[,keep]));rm(ref,x,xx);gc()
fit<-create.RCTD(sp,reference,max_cores=4,UMI_min=100,UMI_min_sigma=300,counts_MIN=10,keep_reference=FALSE);write_json(fit@config,file.path(root,'models',paste0(unit,'_RCTD_config.json')),auto_unbox=TRUE,pretty=TRUE);cat('FIT',unit,ncol(fit@spatialRNA@counts),'\n');flush.console();fit<-run.RCTD(fit,doublet_mode='doublet')
z<-as.data.frame(fit@results$results_df);z$bin_id<-rownames(z);w<-as.matrix(fit@results$weights_doublet);put(cbind(data.frame(bin_id=rownames(w)),as.data.frame(w)),paste0(unit,'_rctd_weights.tsv.gz'));put(z,paste0(unit,'_rctd_results.tsv.gz'))
full<-d[,c('bin_id','roi','nCount_RNA','nFeature_RNA','qc_keep','x_um','y_um')];full$status<-ifelse(!d$qc_keep,'not_expression_QC',ifelse(d$nCount_RNA<100,'below_UMI100','excluded_algorithm_gene_count_gate'));ii<-match(full$bin_id,z$bin_id);full$status[!is.na(ii)]<-as.character(z$spot_class[ii[!is.na(ii)]]);put(full,paste0(unit,'_rctd_coverage.tsv.gz'));write_json(list(unit=unit,n_input=nrow(d),n_fit=nrow(z),statuses=as.list(setNames(as.integer(table(full$status)),names(table(full$status)))),weight_dim=dim(w),weight_columns=colnames(w),weight_row_sums=as.numeric(summary(rowSums(w))),version=as.character(packageVersion('spacexr'))),file.path(root,'tables',paste0(unit,'_rctd_summary.json')),auto_unbox=TRUE,pretty=TRUE);writeLines(capture.output(str(fit@results,max.level=2)),file.path(root,'logs',paste0(unit,'_rctd_structure.txt')));cat('RCTD_COMPLETE\n')
